from gigachat.models.auth import AccessToken, Token
from tests.constants import EXPIRES_AT_VALID, PASSWORD_EXPIRES_AT_VALID


def test_access_token_creation() -> None:
    data = {"access_token": "token-123", "expires_at": EXPIRES_AT_VALID}
    token = AccessToken.model_validate(data)
    assert token.access_token == "token-123"
    assert token.expires_at == EXPIRES_AT_VALID


def test_access_token_normalizes_seconds() -> None:
    """Backends returning the expiration in seconds must end up in milliseconds."""
    token = AccessToken.model_validate({"access_token": "token-123", "expires_at": PASSWORD_EXPIRES_AT_VALID})
    assert token.expires_at == EXPIRES_AT_VALID


def test_access_token_keeps_milliseconds() -> None:
    token = AccessToken.model_validate({"access_token": "token-123", "expires_at": EXPIRES_AT_VALID})
    assert token.expires_at == EXPIRES_AT_VALID


def test_access_token_keeps_never_expiring() -> None:
    """Zero marks a token without expiration and must not be scaled."""
    token = AccessToken.model_validate({"access_token": "token-123", "expires_at": 0})
    assert token.expires_at == 0


def test_token_creation() -> None:
    data = {"tok": "token-456", "exp": 1234567890}
    token = Token.model_validate(data)
    assert token.tok == "token-456"
    assert token.exp == 1234567890

import base64
import binascii
import logging
import uuid
from http import HTTPStatus
from typing import Any, Dict

import httpx

from gigachat.api.utils import (
    USER_AGENT,
    _raise_for_status,
    build_headers,
    build_x_headers,
    execute_request_async,
    execute_request_sync,
)
from gigachat.models.auth import AccessToken, Token

logger = logging.getLogger(__name__)


def _get_auth_kwargs(*, url: str, credentials: str, scope: str) -> Dict[str, Any]:
    headers = {
        "Authorization": f"Basic {credentials}",
        "RqUID": str(uuid.uuid4()),
        "User-Agent": USER_AGENT,
    }
    return {
        "method": "POST",
        "url": url,
        "data": {"scope": scope},
        "headers": headers,
    }


def _validate_credentials(credentials: str) -> None:
    try:
        base64.b64decode(credentials, validate=True)
    except (ValueError, binascii.Error):
        logger.warning(
            "Invalid credentials format. Please use only base64 credentials (Authorization data, not client secret!)"
        )


def _build_auth_response(response: httpx.Response) -> AccessToken:
    if response.status_code == HTTPStatus.OK:
        json_data = response.json()
        if "tok" in json_data:
            return AccessToken(
                x_headers=build_x_headers(response), access_token=json_data["tok"], expires_at=json_data["exp"]
            )
        else:
            return AccessToken(x_headers=build_x_headers(response), **json_data)
    else:
        _raise_for_status(response.url, response.status_code, response.content, response.headers)


def auth_sync(client: httpx.Client, *, url: str, credentials: str, scope: str) -> AccessToken:
    """Return an access token."""
    _validate_credentials(credentials)
    kwargs = _get_auth_kwargs(url=url, credentials=credentials, scope=scope)
    response = client.request(**kwargs)
    return _build_auth_response(response)


async def auth_async(client: httpx.AsyncClient, *, url: str, credentials: str, scope: str) -> AccessToken:
    """Return an access token."""
    _validate_credentials(credentials)
    kwargs = _get_auth_kwargs(url=url, credentials=credentials, scope=scope)
    response = await client.request(**kwargs)
    return _build_auth_response(response)


def _get_token_kwargs(
    *,
    user: str,
    password: str,
) -> Dict[str, Any]:
    headers = build_headers()

    return {
        "method": "POST",
        "url": "/token",
        "auth": (user, password),
        "headers": headers,
    }


def token_sync(
    client: httpx.Client,
    *,
    user: str,
    password: str,
) -> Token:
    """Return a token."""
    kwargs = _get_token_kwargs(user=user, password=password)
    return execute_request_sync(client, kwargs, Token)


async def token_async(
    client: httpx.AsyncClient,
    *,
    user: str,
    password: str,
) -> Token:
    """Return a token."""
    kwargs = _get_token_kwargs(user=user, password=password)
    return await execute_request_async(client, kwargs, Token)

"""Integration tests for /models endpoint using VCR cassettes."""

import pytest

from gigachat import GigaChat, Model, Models, NotFoundError


@pytest.mark.integration
@pytest.mark.vcr
def test_get_models(gigachat_client: GigaChat) -> None:
    """Test listing all available models."""
    result = gigachat_client.get_models()

    assert isinstance(result, Models)
    assert result.data is not None
    assert len(result.data) > 0


@pytest.mark.integration
@pytest.mark.vcr
def test_get_model(gigachat_client: GigaChat) -> None:
    """Test getting a specific model by name."""
    result = gigachat_client.get_model("GigaChat")

    assert isinstance(result, Model)
    assert result.id_ == "GigaChat"


@pytest.mark.integration
@pytest.mark.vcr
def test_get_model_not_found(gigachat_client: GigaChat) -> None:
    """Test that getting a non-existent model raises NotFoundError."""
    with pytest.raises(NotFoundError) as exc_info:
        gigachat_client.get_model("NonExistentModel")

    assert exc_info.value.status_code == 404


@pytest.mark.integration
@pytest.mark.vcr
async def test_aget_models(gigachat_async_client: GigaChat) -> None:
    """Test listing all available models asynchronously."""
    result = await gigachat_async_client.aget_models()

    assert isinstance(result, Models)
    assert result.data is not None
    assert len(result.data) > 0


@pytest.mark.integration
@pytest.mark.vcr
async def test_aget_model(gigachat_async_client: GigaChat) -> None:
    """Test getting a specific model by name asynchronously."""
    result = await gigachat_async_client.aget_model("GigaChat")

    assert isinstance(result, Model)
    assert result.id_ == "GigaChat"


@pytest.mark.integration
@pytest.mark.vcr
async def test_aget_model_not_found(gigachat_async_client: GigaChat) -> None:
    """Test that getting a non-existent model asynchronously raises NotFoundError."""
    with pytest.raises(NotFoundError) as exc_info:
        await gigachat_async_client.aget_model("NonExistentModel")

    assert exc_info.value.status_code == 404

